function equalsDivisorSum(num: number): boolean {
  if (num === 1) return false;
  let sum = 1; // 1 divides everything; its partner is num itself, which we skip
  for (let d = 2; d * d <= num; d++) {
    if (num % d === 0) {
      sum += d;
      if (d * d !== num) sum += num / d;
    }
  }
  return sum === num;
}

