class Solution:
    def equalsDivisorSum(self, num: int) -> bool:
        if num == 1:
            return False
        total = 1  # 1 divides everything; its partner is num itself, which we skip
        d = 2
        while d * d <= num:
            if num % d == 0:
                total += d
                if d * d != num:
                    total += num // d
            d += 1
        return total == num

